'use strict';

var GeneralizedScale = require( './../lib' );

var scale = new GeneralizedScale();
console.log( scale.toJSON() );

scale.type = 'linear';
console.log( scale.toJSON() );

scale.type = 'log';
console.log( scale.toJSON() );

scale.type = 'pow';
console.log( scale.toJSON() );

scale.type = 'sqrt';
console.log( scale.toJSON() );

scale.type = 'symlog';
console.log( scale.toJSON() );

scale.type = 'time';
console.log( scale.toJSON() );

scale.type = 'utc';
console.log( scale.toJSON() );
